package com.lynx.core.listeners;

import org.bukkit.*; import org.bukkit.block.*; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.block.Action; import org.bukkit.event.player.PlayerInteractEvent; import org.bukkit.inventory.ItemStack;

public final class ClassicHcfListener implements Listener {
    @EventHandler(ignoreCancelled=true) public void onInteract(PlayerInteractEvent e){ if(e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null) return; Player p=e.getPlayer(); Block b=e.getClickedBlock(); if(b.getState() instanceof Sign){ Sign s=(Sign)b.getState(); if(s.getLine(0).equalsIgnoreCase("[Elevator]")){ boolean up=s.getLine(1).equalsIgnoreCase("Up"); Location target=find(p.getLocation(),up); if(target!=null) p.teleport(target); } } ItemStack hand=p.getItemInHand(); if(b.getType()==Material.MOB_SPAWNER&&hand!=null&&hand.getType()==Material.DIAMOND_HOE&&hand.hasItemMeta()&&hand.getItemMeta().hasDisplayName()&&hand.getItemMeta().getDisplayName().contains("Crowbar")){ b.setType(Material.AIR); b.getWorld().dropItemNaturally(b.getLocation(), new ItemStack(Material.MOB_SPAWNER,1)); hand.setDurability((short)(hand.getDurability()+1)); if(hand.getDurability()>=6) p.setItemInHand(null); p.sendMessage("§eSpawner recovered."); } }
    private Location find(Location from, boolean up){ World w=from.getWorld(); int x=from.getBlockX(), z=from.getBlockZ(); if(up){ for(int y=from.getBlockY()+1;y<w.getMaxHeight()-1;y++) if(w.getBlockAt(x,y,z).getType()==Material.AIR&&w.getBlockAt(x,y+1,z).getType()==Material.AIR) return new Location(w,x+0.5,y,z+0.5,from.getYaw(),from.getPitch()); } else { for(int y=from.getBlockY()-1;y>1;y--) if(w.getBlockAt(x,y,z).getType()==Material.AIR&&w.getBlockAt(x,y+1,z).getType()==Material.AIR) return new Location(w,x+0.5,y,z+0.5,from.getYaw(),from.getPitch()); } return null; }
}
